package in.suniye.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import org.json.*;import java.io.*;
/** Supplied, publicly sourced documents, real local OCR and direct hosted speech. */
public final class RealMediaDemo extends Instrumentation {
 private Bundle args;private Activity activity;private ReaderController reader;private long started;private final JSONArray events=new JSONArray();
 @Override public void onCreate(Bundle args){this.args=args;start();}
 @Override public void onStart(){Bundle result=new Bundle();started=System.currentTimeMillis();String stage=args.getString("stage","image");try{
  getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);
  runOnMainSync(()->{reader=SuniyeApp.reader(getTargetContext());reader.forget();Config c=new Config(getTargetContext());try{c.save(args.getString("endpoint"),args.getString("token"),"real-document-demo");}catch(Exception e){throw new RuntimeException(e);}c.acknowledge();c.setOnlineVoice(true);c.setSpeed(.85f);});
  activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();event("home");Thread.sleep(1000);
  boolean photo=stage.equals("image")||stage.equals("checks");File file=new File(getTargetContext().getFilesDir(),"real-docs/"+(photo?"consumer-hi.png":"up-electricity-notice.pdf"));String mime=photo?"image/png":"application/pdf";Uri uri=store(file,photo?"Consumer-notice.png":"UP-electricity-notice.pdf",mime);
  share(uri,mime);event("shared");awaitReview();event("uncertainty-visible");save("real-"+stage+"-warning.png");
  if(stage.equals("checks")){if(reader.hasLast()||!reader.original().isEmpty()||new File(getTargetContext().getFilesDir(),"last-reading.mp3").exists())throw new AssertionError("Unapproved OCR was uploaded/spoken");runOnMainSync(()->{reader.repeat();reader.slower();reader.explain();reader.readOriginal();});if(!reader.hasUncertainText()||reader.busy()||reader.hasLast())throw new AssertionError("Pending review bypassed by another reading control");runOnMainSync(reader::stop);waitForIdleSync();if(reader.hasUncertainText()||reader.busy()||findButton(activity.getWindow().getDecorView(),"सावधानी से सुनिए")!=null)throw new AssertionError("Stop retained uncertain action");runOnMainSync(reader::forget);if(reader.hasUncertainText()||reader.hasLast())throw new AssertionError("Forget retained source");write("real-checks.json",new JSONObject().put("passed",true).put("checks","Real image OCR waits for explicit review; no cached reading before review; Stop removes pending action; Forget clears state").toString(2));result.putString("result","PASS: uncertain OCR review, Stop and Forget");finish(Activity.RESULT_OK,result);return;}
  if(stage.equals("pdf2")){click("अगला पन्ना");event("next-page");awaitReview();if(SuniyeApp.document(getTargetContext()).page!=1)throw new AssertionError("Page did not advance");}
  if(!photo&&SuniyeApp.document(getTargetContext()).count!=2)throw new AssertionError("Not a two-page PDF");
  String reviewed=reader.displayedText();if(reviewed.startsWith(OcrTranscript.REVIEW_WARNING))throw new AssertionError("Warning contaminated source");Thread.sleep(3500);click("सावधानी से सुनिए");event("review-approved");awaitPlaying();event("playback-start");saveAudio("real-"+stage+".mp3");save("real-"+stage+"-playing.png");
  if(!reader.original().equals(reviewed)||!reader.spoken().startsWith(OcrTranscript.REVIEW_WARNING))throw new AssertionError("Source or separate audible caution missing");click("पूरा पाठ देखिए");showTextBody();save("real-"+stage+"-source.png");event("source-visible");
  awaitComplete();event("playback-complete");Thread.sleep(700);click("फिर सुनिए");awaitPlaying();event("repeat-playing");Thread.sleep(2000);click("रोकिए");event("stop");
  if(reader.busy())throw new AssertionError("Stop did not finish");
  JSONObject receipt=new JSONObject().put("checkedAt",java.time.Instant.now().toString()).put("stage",stage).put("startedAtEpochMs",started).put("events",events).put("recognizedSource",reviewed).put("spokenText",reader.spoken()).put("originalPreservedByBackend",true).put("readingCompleted",true).put("repeatAndStop",true).put("environment","Android "+Build.VERSION.RELEASE+" emulator; font scale "+getTargetContext().getResources().getConfiguration().fontScale).put("input",file.getName()).put("transport","Direct public Render HTTPS, normal certificate validation").put("scope","Public notice content via real ACTION_SEND; OCR review explicitly approved in instrumentation; actual Raju audio and MediaPlayer completion. No external WhatsApp sender exercised.");write("real-"+stage+"-receipt.json",receipt.toString(2));result.putString("result","PASS: real "+stage+" OCR, explicit uncertainty review, full Raju playback, Repeat and Stop");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{write("real-"+stage+"-failure.json",new JSONObject().put("events",events).put("error",e.toString()).toString(2));}catch(Exception ignored){}result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
 private void awaitReview()throws Exception{long end=System.currentTimeMillis()+40000;while(System.currentTimeMillis()<end){waitForIdleSync();if(reader.hasUncertainText()&&!reader.busy())return;if(!reader.busy())throw new AssertionError("Expected review, got "+reader.status());Thread.sleep(100);}throw new AssertionError("Review timeout");}
 private void awaitPlaying()throws Exception{java.lang.reflect.Field f=ReaderController.class.getDeclaredField("player");f.setAccessible(true);long end=System.currentTimeMillis()+80000;while(System.currentTimeMillis()<end){waitForIdleSync();android.media.MediaPlayer p=(android.media.MediaPlayer)f.get(reader);if(reader.busy()&&reader.status().equals("सुनिए।")||reader.status().equals("फिर सुनिए।")){try{if(p!=null&&p.isPlaying())return;}catch(IllegalStateException ignored){}}if(!reader.busy())throw new AssertionError("Speech failed "+reader.status());Thread.sleep(100);}throw new AssertionError("No hosted playback");}
 private void awaitComplete()throws Exception{long end=System.currentTimeMillis()+300000;while(System.currentTimeMillis()<end){waitForIdleSync();if(!reader.busy()){if(!reader.status().startsWith("फिर सुनने"))throw new AssertionError("Playback failed "+reader.status());return;}Thread.sleep(200);}throw new AssertionError("Playback timeout");}
 private void showTextBody()throws Exception{runOnMainSync(()->{TextView t=findText(activity.getWindow().getDecorView(),reader.original());if(t==null||t.getLayout()==null)return;int line=t.getLayout().getLineForOffset(0);int y=t.getLayout().getLineTop(line);t.requestRectangleOnScreen(new Rect(0,y,t.getWidth(),y+Math.min(500,t.getHeight()-y)),true);});waitForIdleSync();Thread.sleep(500);}
 private TextView findText(View v,String expected){if(v instanceof TextView&&expected.contentEquals(((TextView)v).getText()))return(TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=findText(g.getChildAt(i),expected);if(t!=null)return t;}}return null;}
 private void saveAudio(String name)throws Exception{java.nio.file.Files.copy(new File(getTargetContext().getFilesDir(),"last-reading.mp3").toPath(),new File(getTargetContext().getFilesDir(),name).toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
 private Uri store(File file,String name,String type)throws Exception{android.database.Cursor old=getTargetContext().getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{MediaStore.Downloads._ID},MediaStore.Downloads.DISPLAY_NAME+"=?",new String[]{name},null);if(old!=null){try{while(old.moveToNext())getTargetContext().getContentResolver().delete(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,old.getLong(0)),null,null);}finally{old.close();}}ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,name);values.put(MediaStore.Downloads.MIME_TYPE,type);values.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS);Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Fixture insert failed");try(InputStream in=new FileInputStream(file);OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}return uri;}
 private void share(Uri uri,String type)throws Exception{runOnMainSync(()->activity.startActivity(new Intent(Intent.ACTION_SEND).setClass(getTargetContext(),MainActivity.class).setType(type).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION)));waitForIdleSync();}
 private void scrollTo(String text)throws Exception{for(int i=0;i<8;i++){AccessibilityNodeInfo root=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).getRootInActiveWindow();if(root==null)throw new AssertionError("No help window");AccessibilityNodeInfo n=find(root,text);if(n!=null&&n.isVisibleToUser()){n.recycle();root.recycle();return;}if(n!=null)n.recycle();AccessibilityNodeInfo scroll=scrollable(root);root.recycle();if(scroll==null)throw new AssertionError("No help scroll");scroll.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);scroll.recycle();Thread.sleep(500);}throw new AssertionError("Help section not reached");}
 private AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if((n.getText()!=null&&text.contentEquals(n.getText()))||(n.getContentDescription()!=null&&(text.contentEquals(n.getContentDescription())||n.getContentDescription().toString().startsWith(text+","))))return AccessibilityNodeInfo.obtain(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){AccessibilityNodeInfo found=find(c,text);c.recycle();if(found!=null)return found;}}return null;}
 private AccessibilityNodeInfo scrollable(AccessibilityNodeInfo n){if(n.isScrollable())return AccessibilityNodeInfo.obtain(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){AccessibilityNodeInfo found=scrollable(c);c.recycle();if(found!=null)return found;}}return null;}
 private void click(String label)throws Exception{runOnMainSync(()->{Button b=findButton(activity.getWindow().getDecorView(),label);if(b==null)throw new AssertionError("Missing button "+label);b.requestRectangleOnScreen(new Rect(0,0,b.getWidth(),b.getHeight()),true);});waitForIdleSync();Thread.sleep(350);runOnMainSync(()->findButton(activity.getWindow().getDecorView(),label).performClick());}
 private Button findButton(View view,String text){if(view instanceof Button&&text.contentEquals(((Button)view).getText()))return(Button)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){Button b=findButton(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private void event(String name)throws Exception{events.put(new JSONObject().put("name",name).put("elapsedMs",System.currentTimeMillis()-started));}
 private void write(String name,String text)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){out.write(text.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 private void save(String name)throws Exception{Bitmap b=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();if(b==null)throw new AssertionError("Screenshot absent");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
}
